package com.healthcompanion.ai; import com.healthcompanion.domain.KnowledgeChunk; import com.healthcompanion.repository.KnowledgeChunkRepository; import java.util.*; import org.springframework.stereotype.Service;
@Service public class MedicalKnowledgeRagService {private final KnowledgeChunkRepository chunks;private final EmbeddingGateway embeddings;private final PgVectorStore vectors;public MedicalKnowledgeRagService(KnowledgeChunkRepository c,EmbeddingGateway e,PgVectorStore v){chunks=c;embeddings=e;vectors=v;}public String retrieve(String question){var byId=new HashMap<Long,KnowledgeChunk>();chunks.findAll().forEach(c->byId.put(c.id,c));return vectors.nearestKnowledgeChunks(embeddings.embed(question),embeddings.profile(),4).stream().map(byId::get).filter(Objects::nonNull).map(c->c.content).reduce("",(a,b)->a+"\n"+b);}}
